    sse_encode_u_64(self.totpPeriodSecs, serializer);
    sse_encode_opt_String(self.url, serializer);
    sse_encode_opt_String(self.notes, serializer);
  }

  @protected
  void sse_encode_vault_entry_summary_dto(
    VaultEntrySummaryDto self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_String(self.id, serializer);
    sse_encode_String(self.title, serializer);
    sse_encode_String(self.username, serializer);
    sse_encode_bool(self.hasTotp, serializer);
    sse_encode_opt_String(self.url, serializer);
    sse_encode_i_64(self.updatedAt, serializer);
  }

  @protected
  void sse_encode_vlt_inspect_dto(
    VltInspectDto self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_u_32(self.version, serializer);
    sse_encode_String(self.cipher, serializer);
    sse_encode_usize(self.directSlotCount, serializer);
    sse_encode_u_8(self.quorumThresholdK, serializer);
    sse_encode_u_8(self.quorumTotalN, serializer);
    sse_encode_String(self.headerSha256Hex, serializer);
    sse_encode_bool(self.signatureValid, serializer);
  }
}
